import session, { type SessionData } from 'express-session';

declare module 'express-session' {
  interface SessionData { cart?: Cart; step?: 'cart' | 'payment'; }
}

app.use(session({ store: redisStore, secret: SECRET, resave: false, saveUninitialized: false }));
app.get('/cart', (req, res) => {
  const step: 'cart' | 'payment' | undefined = req.session.step;   // typed access
  res.json({ step });
});
